/* Smart Healthcare 3-role MOBILE UI — standalone demo, local-only sample data. */
const MENUS={
 admin:[['dashboard','📊','Tổng quan','Dashboard'],['approvals','🗓️','Yêu cầu đặt lịch','Lịch khám'],['doctors','👨‍⚕️','Quản lý bác sĩ','Bác sĩ'],['patients','👥','Quản lý bệnh nhân','Bệnh nhân'],['work','📅','Lịch làm việc','Lịch làm'],['specialties','🧬','Danh mục chuyên khoa','Danh mục'],['notifications','🔔','Thông báo','Thông báo'],['reports','📈','Thống kê báo cáo','Báo cáo']],
 doctor:[['doctorHome','🏠','Tổng quan bác sĩ','Trang chủ'],['doctorAppointments','📋','Lịch khám cá nhân','Lịch khám'],['assignedPatients','👥','Bệnh nhân được phân công','Bệnh nhân'],['exam','🩺','Kết quả khám','Kết quả'],['prescriptions','💊','Đơn thuốc điện tử','Đơn thuốc'],['doctorChat','💬','Chat tư vấn','Tin nhắn'],['doctorSchedule','📅','Thời gian làm việc','Lịch làm'],['doctorProfile','👤','Hồ sơ cá nhân','Hồ sơ']],
 patient:[['auth','🔐','Đăng ký & đăng nhập','Tài khoản'],['patientHome','🏠','Trang chủ bệnh nhân','Trang chủ'],['searchDoctors','🔍','Tìm bác sĩ & chuyên khoa','Tìm bác sĩ'],['booking','📅','Đặt lịch khám','Đặt lịch'],['myAppointments','📋','Quản lý lịch khám','Lịch của tôi'],['patientChat','💬','Chat tư vấn bác sĩ','Tin nhắn'],['records','📂','Hồ sơ sức khỏe','Hồ sơ'],['reminders','💊','Nhắc thuốc & tái khám','Nhắc thuốc'],['reviews','⭐','Đánh giá & phản hồi','Đánh giá'],['settings','⚙️','Thông báo & cài đặt','Cài đặt']]
};
const TITLES={admin:'Quản trị viên',doctor:'Bác sĩ',patient:'Bệnh nhân'};
const ICONS={admin:'🧑🏻‍💼',doctor:'👨🏻‍⚕️',patient:'👩🏻'};
const nowDate='2026-11-17';
const seed={
 doctors:[{id:'d1',name:'Trần Minh Đức',specialty:'Nội tổng quát',experience:12,rating:4.9,emoji:'👨🏻‍⚕️',active:true,phone:'0987 654 321'},{id:'d2',name:'Lê Thị Hạnh',specialty:'Tim mạch',experience:9,rating:4.8,emoji:'👩🏻‍⚕️',active:true,phone:'0984 321 654'},{id:'d3',name:'Phạm Gia Huy',specialty:'Nhi khoa',experience:8,rating:4.8,emoji:'👨🏽‍⚕️',active:true,phone:'0975 111 222'},{id:'d4',name:'Nguyễn Hoàng Long',specialty:'Cơ xương khớp',experience:14,rating:4.7,emoji:'👨🏼‍⚕️',active:true,phone:'0988 222 100'}],
 patients:[{id:'p1',name:'Nguyễn Văn An',age:28,phone:'0987 654 321',email:'an.nguyen@gmail.com',emoji:'👨🏻',active:true},{id:'p2',name:'Lê Thị Mai',age:31,phone:'0988 111 222',email:'mai.le@gmail.com',emoji:'👩🏻',active:true},{id:'p3',name:'Phạm Gia Huy',age:35,phone:'0976 222 333',email:'huy.pham@gmail.com',emoji:'👨🏽',active:true}],
 appointments:[{id:'K001',pid:'p1',did:'d1',date:nowDate,time:'08:30',status:'pending',reason:'Khám tổng quát'},{id:'K002',pid:'p2',did:'d1',date:nowDate,time:'08:30',status:'pending',reason:'Đau đầu, mệt mỏi'},{id:'K003',pid:'p3',did:'d1',date:nowDate,time:'08:30',status:'pending',reason:'Tư vấn sức khỏe'},{id:'K004',pid:'p1',did:'d2',date:nowDate,time:'10:00',status:'confirmed',reason:'Tái khám tim mạch'},{id:'K005',pid:'p1',did:'d1',date:'2026-11-12',time:'09:00',status:'completed',reason:'Đau họng'}],
 specialties:[{id:'s1',name:'Nội tổng quát',icon:'🩺',active:true},{id:'s2',name:'Tim mạch',icon:'❤️',active:true},{id:'s3',name:'Nhi khoa',icon:'🧸',active:true},{id:'s4',name:'Cơ xương khớp',icon:'🦴',active:true},{id:'s5',name:'Tai – Mũi – Họng',icon:'👂',active:true},{id:'s6',name:'Da liễu',icon:'🧴',active:true}],
 medications:[{id:'m1',name:'Paracetamol 500 mg',dosage:'1 viên/lần, 2 lần/ngày',times:['08:00','20:00'],active:true,taken:false},{id:'m2',name:'Amoxicillin 500 mg',dosage:'Theo đơn bác sĩ',times:['09:00','14:00','20:00'],active:false,taken:false}],
 messages:[{role:'doctor',text:'Chào bạn, bạn đang cần tư vấn vấn đề gì?',time:'09:20'},{role:'patient',text:'Em muốn hỏi về lịch tái khám.',time:'09:21'},{role:'doctor',text:'Bạn có thể đặt lịch qua ứng dụng nhé.',time:'09:22'}],
 notifications:[{text:'Chào mừng bạn đến với Smart Healthcare',role:'all',date:'17/11/2026'},{text:'Lịch khám 10:00 của bạn đã được xác nhận',role:'patient',date:'17/11/2026'}],
 results:[{pid:'p1',did:'d1',appointmentId:'K005',diagnosis:'Viêm họng cấp',treatment:'Nghỉ ngơi, uống đủ nước, theo dõi triệu chứng',advice:'Tái khám nếu triệu chứng kéo dài',published:true}],
 prescriptions:[{pid:'p1',did:'d1',appointmentId:'K005',items:[{name:'Paracetamol 500 mg',dosage:'Theo hướng dẫn bác sĩ',days:'3'}]}],
 leaveRequests:[],reviews:[],lockedSlots:[]
};
const STORAGE_KEY='smart-healthcare-ui-v3';let db;
try{db=JSON.parse(localStorage.getItem(STORAGE_KEY))||structuredClone(seed)}catch{db=JSON.parse(JSON.stringify(seed))}
const ui={role:'patient',page:'patientHome',drawer:false,modal:false,filter:'all',search:'',doctor:'d1',patient:'p1',selectedAppt:'K001',selectedPatient:'p1',bookingStep:1,date:nowDate,time:'08:30',bookingReason:'',specialty:'Tất cả',rating:5,authMode:'login',selectedTab:'pending',examDraft:{diagnosis:'',treatment:'',advice:''},workDate:nowDate};
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const add30=t=>{let [hh,mm]=t.split(':').map(Number),total=hh*60+mm+30;return String(Math.floor(total/60)%24).padStart(2,'0')+':'+String(total%60).padStart(2,'0')};
const doc=id=>db.doctors.find(x=>x.id===id)||db.doctors[0],pat=id=>db.patients.find(x=>x.id===id)||db.patients[0],fmtDate=s=>s?`${s.slice(8,10)}/${s.slice(5,7)}/${s.slice(0,4)}`:'—';
const badge=s=>{let m={pending:['Chờ duyệt','pending'],confirmed:['Đã xác nhận','confirmed'],completed:['Hoàn thành','completed'],cancelled:['Đã hủy','cancelled'],rejected:['Từ chối','rejected'],proposed:['Đề xuất giờ','proposed'],inprogress:['Đang khám','inprogress']};let a=m[s]||[s,''];return `<span class="status ${a[1]}">${a[0]}</span>`};
const save=()=>{try{localStorage.setItem(STORAGE_KEY,JSON.stringify(db))}catch{}};
const btn=(label,action,cls='secondary',extra='')=>`<button type="button" class="button ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const kv=(a,b)=>`<div class="kv"><span>${a}</span><b>${b}</b></div>`;
const section=(s,action='',label='Xem tất cả')=>`<div class="section-caption"><b>${s}</b>${action?`<button class="plain-btn" data-action="${action}">${label} ›</button>`:''}</div>`;
const card=txt=>`<div class="card">${txt}</div>`;
const formField=(label,name,placeholder='',value='',type='text',required=false)=>`<label class="field">${label}<input class="input" name="${name}" type="${type}" placeholder="${esc(placeholder)}" value="${esc(value)}" ${required?'required':''}></label>`;
const textarea=(label,name,value='',placeholder='Nhập nội dung')=>`<label class="field">${label}<textarea class="textarea" name="${name}" placeholder="${esc(placeholder)}">${esc(value)}</textarea></label>`;
const selectField=(label,name,opts,selected)=>`<label class="field">${label}<select class="select" name="${name}">${opts.map(o=>`<option value="${esc(o[0])}" ${o[0]===selected?'selected':''}>${esc(o[1])}</option>`).join('')}</select></label>`;
const kpi=(icon,value,name,cls='blue',action='')=>`<div class="kpi ${cls}" ${action?`data-action="${action}" style="cursor:pointer"`:''}><div class="kpi-icon">${icon}<span style="font-size:12px;color:#b2c0d1">↗</span></div><div class="kpi-value">${value}</div><div class="kpi-name">${name}</div></div>`;
const chips=(items,chosen,prefix)=>`<div class="chip-row">${items.map(i=>`<button class="chip ${i[0]===chosen?'active':''}" data-action="${prefix}" data-value="${esc(i[0])}">${esc(i[1])}</button>`).join('')}</div>`;
function personRow(person,subtitle,right='',action='',id=''){return `<div class="list-card" ${action?`data-action="${action}" data-id="${esc(id)}"`:''}><span class="person-avatar">${person.emoji||'👤'}</span><div class="person-info"><strong>${esc(person.name)}</strong><small>${esc(subtitle)}</small></div><div class="list-right">${right||'<span class="list-arrow">›</span>'}</div></div>`}
function apptRow(a,action='apptDetail'){let p=pat(a.pid),d=doc(a.did);return `<div class="list-card" data-action="${action}" data-id="${esc(a.id)}"><span class="person-avatar">${ui.role==='patient'?d.emoji:p.emoji}</span><div class="person-info"><strong>${esc(ui.role==='patient'?'BS. '+d.name:p.name)}</strong><small>${fmtDate(a.date)} · ${a.time} · ${esc(ui.role==='patient'?d.specialty:a.reason)}</small><small>${badge(a.status)}</small></div><span class="list-arrow">›</span></div>`}
const chart=(arr=[32,54,45,75,62,84,69])=>`<div class="mini-chart">${arr.map((n,i)=>`<div class="chart-col"><div class="chart-bar" style="height:${n}%"></div><span>${['T2','T3','T4','T5','T6','T7','CN'][i]}</span></div>`).join('')}</div>`;
const infobox=(text,kind='')=>`<div class="info-box ${kind}"><span class="alert-icon">${kind==='warn'?'⚠️':kind==='success'?'✅':'ℹ️'}</span><span>${text}</span></div>`;
function openModal(title,body){$('#modalRoot').innerHTML=`<div class="modal-backdrop" data-action="closeModal"><div class="modal-panel"><div class="modal-head"><h2>${title}</h2><button class="x-btn" data-action="closeModal">×</button></div>${body}</div></div>`;ui.modal=true}
function closeModal(){ui.modal=false;$('#modalRoot').innerHTML=''}
let toastTimer;function toast(msg){const e=$('#toastRoot');e.innerHTML=`<div class="toast">${esc(msg)}</div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.innerHTML='',2400)}
function setRole(role){ui.role=role;ui.page={admin:'dashboard',doctor:'doctorHome',patient:'patientHome'}[role];ui.filter='all';ui.search='';ui.drawer=false;closeModal();render()}
function go(page){ui.page=page;ui.search='';ui.drawer=false;closeModal();render()}
function navButton(v){return `<button class="nav-item ${ui.page===v[0]?'active':''}" data-action="go" data-page="${v[0]}"><span class="nav-symbol">${v[1]}</span><span>${v[3]}</span></button>`}
function renderShell(){document.body.dataset.role=ui.role;const menu=MENUS[ui.role],meta=TITLES[ui.role];$('#roleSwitcher').innerHTML=['admin','doctor','patient'].map(r=>`<button class="role-btn ${r===ui.role?'active':''}" data-action="role" data-role="${r}"><span class="role-symbol">${ICONS[r]}</span><span><b>${TITLES[r]}</b><small>8${r==='patient'?' + 2':''} nhóm chức năng</small></span></button>`).join('');$('#mobileSwitcher').innerHTML=['admin','doctor','patient'].map(r=>`<button data-action="role" data-role="${r}" class="${r===ui.role?'active':''}">${ICONS[r]} ${TITLES[r]}</button>`).join('');$('#roleLabel').textContent=meta;$('#pageIndex').innerHTML=menu.map(v=>`<button class="index-entry ${ui.page===v[0]?'active':''}" data-action="go" data-page="${v[0]}"><span>${v[1]}</span>${v[2]}</button>`).join('');let current=menu.find(x=>x[0]===ui.page)||menu[0];$('#appHeader').innerHTML=`<div class="topbar"><div class="topbar-line"><button class="topbar-icon" data-action="drawer">☰</button><div class="topbar-spacer"><div class="topbar-eyebrow">Smart Healthcare · ${meta}</div><div class="topbar-title">${current[2]}</div></div><button class="topbar-icon" data-action="go" data-page="${ui.role==='patient'?'settings':ui.role==='doctor'?'doctorProfile':'notifications'}">🔔</button></div></div>`;let items=menu.slice(0,4);$('#bottomNav').innerHTML=`<div class="bottom-list">${[...items].map(navButton).join('')}<button class="nav-item" data-action="drawer"><span class="nav-symbol">☷</span><span>Danh mục</span></button></div>`;$('#drawerRoot').innerHTML=ui.drawer?`<div class="drawer-backdrop" data-action="drawer"><div class="drawer-panel"><div class="drawer-header"><strong>📱 ${meta} · Các chức năng</strong><button class="x-btn" data-action="drawer">×</button></div><div class="drawer-group">${menu.length} nhóm chức năng mobile</div>${menu.map(v=>`<button class="drawer-item ${ui.page===v[0]?'active':''}" data-action="go" data-page="${v[0]}"><i>${v[1]}</i>${v[2]}</button>`).join('')}<div class="divider"></div><button class="drawer-item" data-action="reset"><i>↺</i>Đặt lại dữ liệu demo</button></div></div>`:''}
function render(){renderShell();$('#appContent').innerHTML=pageContent();$('#appContent').scrollTop=0}
function pageContent(){return ({dashboard,approvals,doctors,patients,work,specialties,notifications,reports,doctorHome,doctorAppointments,assignedPatients,exam,prescriptions,doctorChat,doctorSchedule,doctorProfile,auth,patientHome,searchDoctors,booking,myAppointments,patientChat,records,reminders,reviews,settings})[ui.page]?.()||card('Đang thiết kế màn hình')}
// ========= ADMIN · 8 groups =========
function dashboard(){let pending=db.appointments.filter(a=>a.status==='pending').length,confirmed=db.appointments.filter(a=>a.status==='confirmed').length;return `<div class="hero"><div><div class="hero-badge">CHÀO MỪNG TRỞ LẠI 👋</div><h2>Xin chào,<br>Quản trị viên</h2><p>Kiểm soát hoạt động khám chữa bệnh</p></div><div class="hero-icon">🏥</div></div><div class="kpi-grid">${kpi('👨‍⚕️',db.doctors.length,'Tổng bác sĩ','blue','goDoctors')}${kpi('👥',db.patients.length,'Bệnh nhân','green','goPatients')}${kpi('🗓️',db.appointments.filter(a=>a.date===nowDate).length,'Lịch hôm nay','violet','goApprovals')}${kpi('⏱️',pending,'Chờ xác nhận','orange','goApprovals')}</div>${section('Lượt khám trong tuần','goReports')}${card(`<b style="font-size:12px">Biểu đồ theo ngày</b>${chart()}<div class="subtle">Dữ liệu minh họa · Tháng 11/2026</div>`)}${section('Yêu cầu mới','goApprovals','Xử lý ngay')}${db.appointments.filter(a=>a.status==='pending').slice(0,2).map(a=>apptRow(a)).join('')}${btn('➜  Xem tất cả yêu cầu','goApprovals','secondary block')}`}
function approvals(){let statuses=[['all','Tất cả'],['pending','Chờ duyệt'],['confirmed','Đã xác nhận'],['rejected','Từ chối']];let arr=db.appointments.filter(a=>ui.filter==='all'||a.status===ui.filter);let conflicts=db.appointments.filter(a=>a.did==='d1'&&a.date===nowDate&&a.time==='08:30'&&a.status==='pending');return `${conflicts.length>1?infobox(`<b>Trùng khung giờ 08:30:</b> ${conflicts.length} người cùng yêu cầu khám BS. Trần Minh Đức. <button class="plain-btn" data-action="showConflict">Xử lý ngay</button>`,'warn'):''}<div class="page-head"><h2>Danh sách yêu cầu</h2><small>${arr.length} lịch</small></div>${chips(statuses,ui.filter,'filter')}${arr.length?arr.map(a=>apptRow(a)).join(''):'<div class="empty"><span class="empty-icon">🗓️</span>Chưa có lịch ở trạng thái này</div>'}${btn('⚠️  Kiểm tra lịch trùng','showConflict','secondary block')}`}
function doctors(){let arr=db.doctors.filter(x=>(x.name+' '+x.specialty).toLowerCase().includes(ui.search.toLowerCase()));return `${section('Danh sách bác sĩ','openDoctorForm','+ Thêm mới')}<input class="search" placeholder="🔍 Tìm bác sĩ hoặc chuyên khoa..." value="${esc(ui.search)}" data-search="1">${arr.map(d=>personRow(d,'BS. '+d.specialty,`<span class="status ${d.active?'confirmed':'rejected'}">${d.active?'Hoạt động':'Đã khóa'}</span>`,'doctorDetail',d.id)).join('')}${btn('+  Thêm bác sĩ','openDoctorForm','block')}`}
function patients(){let arr=db.patients.filter(x=>(x.name+' '+x.email+' '+x.phone).toLowerCase().includes(ui.search.toLowerCase()));return `${section('Hồ sơ bệnh nhân')}<input class="search" placeholder="🔍 Tên, số điện thoại, email..." value="${esc(ui.search)}" data-search="1">${arr.map(p=>personRow(p,p.phone,`<span class="status ${p.active?'confirmed':'rejected'}">${p.active?'Đang dùng':'Đã khóa'}</span>`,'patientDetail',p.id)).join('')}${infobox('Quản trị viên chỉ được hỗ trợ tài khoản và lịch hẹn; không sửa chẩn đoán hay đơn thuốc.')}`}
function work(){let a=db.lockedSlots.filter(x=>x.date===ui.workDate);return `${card(`<div class="page-head"><h2>Lịch làm việc bác sĩ</h2><span class="pill-date">Tháng 11/2026</span></div>${selectField('Chọn bác sĩ','scheduleDoctor',db.doctors.map(d=>[d.id,'BS. '+d.name]),ui.doctor)}<div class="week-row">${['T3','T4','T5','T6','T7','CN','T2'].map((day,i)=>`<button class="day-box ${ui.workDate===`2026-11-${String(17+i).padStart(2,'0')}`?'active':''}" data-action="workDay" data-date="2026-11-${String(17+i).padStart(2,'0')}"><small>${day}</small>${17+i}</button>`).join('')}</div>`)}${section('Các ca ngày '+fmtDate(ui.workDate))}${['08:00','08:30','09:00','09:30','10:00','13:30','14:00','14:30'].map(t=>{let locked=a.some(x=>x.time===t&&x.did===ui.doctor),used=db.appointments.some(x=>x.did===ui.doctor&&x.date===ui.workDate&&x.time===t&&x.status==='confirmed');return `<div class="list-card"><span class="person-avatar ${used?'pink':'green'}">${used?'🔒':'🕒'}</span><div class="person-info"><strong>${t} – ${add30(t)}</strong><small>${used?'Đã có lịch xác nhận':locked?'Đã khóa nhận lịch':'Còn trống'}</small></div><button class="button small ${locked?'green':'secondary'}" data-action="toggleSlot" data-time="${t}">${used?'Đã đặt':locked?'Mở ca':'Khóa ca'}</button></div>`}).join('')}${btn('+ Tạo ca / Xin nghỉ','newWorkShift','block')}${db.leaveRequests.length?`${section('Yêu cầu nghỉ / đổi ca từ bác sĩ')}${db.leaveRequests.map((r,i)=>card(`<b style="font-size:12px">${r.type==='leave'?'Xin nghỉ':'Đổi ca'} · ${fmtDate(r.date)}</b><div class="subtle">${esc(r.reason)}</div><div style="margin:8px 0">${badge(r.status)}</div>${r.status==='pending'?`<div class="button-row">${btn('Duyệt yêu cầu','approveLeave','green small',`data-id="${i}"`)}${btn('Từ chối','rejectLeave','danger small',`data-id="${i}"`)}</div>`:''}`)).join('')}`:''}`}
function specialties(){return `${section('Chuyên khoa bệnh viện','openSpecialtyForm','+ Thêm')}${db.specialties.map(s=>`<div class="list-card" data-action="specialtyDetail" data-id="${s.id}"><span class="person-avatar">${s.icon}</span><div class="person-info"><strong>${esc(s.name)}</strong><small>${db.doctors.filter(d=>d.specialty===s.name).length} bác sĩ · ${s.active?'Đang hiển thị':'Đã ẩn'}</small></div><span class="list-arrow">›</span></div>`).join('')}${btn('+ Thêm chuyên khoa','openSpecialtyForm','block')}${infobox('Chuyên khoa có liên kết với bác sĩ hoặc lịch khám sẽ được ẩn thay vì xóa cứng.')}`}
function notifications(){let ns=db.notifications.slice().reverse();return `${section('Trung tâm thông báo','composeNotification','+ Soạn tin')}${card(`<b style="font-size:12px">Mẫu thông báo tự động</b><div class="divider"></div>${['✅ Lịch đã xác nhận','🔄 Đề xuất đổi giờ khám','❌ Lịch bị từ chối','💊 Nhắc uống thuốc'].map(x=>`<div class="toggle-row">${x}<span class="status confirmed">Đang bật</span></div>`).join('')}`)}${section('Lịch sử đã gửi')}${ns.map(n=>card(`<div style="font-weight:750;font-size:12px">🔔 ${esc(n.text)}</div><div class="subtle" style="margin-top:7px">Gửi tới: ${n.role==='all'?'Tất cả':TITLES[n.role]} · ${n.date}</div>`)).join('')}${btn('📨 Soạn thông báo','composeNotification','block')}`}
function reports(){let confirmed=db.appointments.filter(a=>a.status==='confirmed').length,completed=db.appointments.filter(a=>a.status==='completed').length,declined=db.appointments.filter(a=>['rejected','cancelled'].includes(a.status)).length;return `${card(`<div class="page-head"><h2>Báo cáo tổng hợp</h2><span class="pill-date">11/2026</span></div>${selectField('Thời gian báo cáo','reportPeriod',[['week','7 ngày gần nhất'],['month','Tháng 11/2026'],['year','Năm 2026']],'month')}`)}<div class="kpi-grid">${kpi('📋',db.appointments.length,'Yêu cầu đặt khám')}${kpi('✅',confirmed,'Đã xác nhận','green')}${kpi('🩺',completed,'Hoàn thành','violet')}${kpi('📌',declined,'Hủy / từ chối','orange')}</div>${card(`<b style="font-size:12px">Lượt khám theo ngày</b>${chart([39,55,70,62,86,73,100])}<div class="subtle">Minh họa cho thiết kế biểu đồ</div>`)}${section('Theo chuyên khoa')}${db.specialties.slice(0,4).map((s,i)=>`<div class="card"><div class="kv"><span>${s.icon} ${esc(s.name)}</span><b>${[42,34,27,18][i]} lượt</b></div><div style="height:6px;border-radius:8px;background:#e8eef7;margin-top:8px"><div style="width:${[82,65,49,31][i]}%;height:100%;background:var(--accent);border-radius:8px"></div></div></div>`).join('')}${btn('↓ Xuất bảng CSV demo','exportReport','block')}`}
// ========= DOCTOR · 8 groups =========
function doctorHome(){let list=db.appointments.filter(a=>a.did==='d1'&&['confirmed','inprogress'].includes(a.status));return `<div class="hero"><div><span class="hero-badge">KHU VỰC BÁC SĨ</span><h2>Chào BS.<br>Trần Minh Đức 👋</h2><p>Chúc một ngày làm việc hiệu quả!</p></div><div class="hero-icon">🩺</div></div><div class="kpi-grid">${kpi('🗓️',list.length,'Lịch được duyệt','blue','goDoctorAppointments')}${kpi('⏳',db.appointments.filter(a=>a.did==='d1'&&a.status==='pending').length,'Chờ Admin duyệt','orange')}${kpi('👥',new Set(list.map(a=>a.pid)).size,'Bệnh nhân hôm nay','green','goAssignedPatients')}${kpi('✅',db.appointments.filter(a=>a.did==='d1'&&a.status==='completed').length,'Đã hoàn thành','violet')}</div>${section('Lịch khám gần nhất','goDoctorAppointments')}${list.length?list.map(a=>apptRow(a)).join(''):infobox('Chưa có lịch khám đã xác nhận. Khi Admin duyệt, lịch sẽ xuất hiện tại đây.')}${section('Tiện ích bác sĩ')}<div class="tile-grid">${[['🩺','Nhập kết quả','goExam'],['💊','Kê đơn','goPrescriptions'],['💬','Chat bệnh nhân','goDoctorChat'],['📅','Lịch làm việc','goDoctorSchedule']].map(x=>`<button class="tile" data-action="${x[2]}"><span class="tile-ico">${x[0]}</span><span class="tile-label">${x[1]}</span></button>`).join('')}</div>`}
function doctorAppointments(){let a=db.appointments.filter(a=>a.did==='d1'&&['confirmed','inprogress','completed'].includes(a.status));return `${card(`<div class="page-head"><h2>Lịch khám cá nhân</h2><span class="pill-date">${fmtDate(nowDate)}</span></div>${chips([['all','Tất cả'],['confirmed','Đã duyệt'],['inprogress','Đang khám'],['completed','Đã khám']],ui.filter,'filter')}`)}${a.filter(x=>ui.filter==='all'||x.status===ui.filter).map(x=>apptRow(x)).join('')||'<div class="empty"><span class="empty-icon">📅</span>Chưa có lịch phù hợp</div>'}${infobox('Bác sĩ chỉ nhận lịch do Admin đã duyệt. Nếu muốn nghỉ hoặc đổi ca, hãy gửi yêu cầu tại Lịch làm việc.')}`}
function assignedPatients(){let ids=[...new Set(db.appointments.filter(a=>a.did==='d1').map(a=>a.pid))],ps=db.patients.filter(p=>ids.includes(p.id));return `${section('Bệnh nhân được phân công')}<input class="search" placeholder="🔍 Tìm theo tên bệnh nhân..." data-search="1" value="${esc(ui.search)}">${ps.filter(p=>p.name.toLowerCase().includes(ui.search.toLowerCase())).map(p=>personRow(p,`${p.age} tuổi · ${p.phone}`,'','doctorPatientDetail',p.id)).join('')}${infobox('Danh sách giới hạn theo bác sĩ đang đăng nhập. Chỉ xem hồ sơ có quyền truy cập.')}`}
function exam(){let a=db.appointments.filter(a=>a.did==='d1'&&['confirmed','inprogress','completed'].includes(a.status));return `${section('Ghi nhận kết quả khám')}${a.map(ap=>`<div class="list-card" data-action="editExam" data-id="${ap.id}"><span class="person-avatar">🩺</span><div class="person-info"><strong>${pat(ap.pid).name}</strong><small>${fmtDate(ap.date)} · ${ap.time}</small><small>${db.results.some(r=>r.appointmentId===ap.id&&r.published)?'✅ Đã công bố kết quả':'✍️ Chưa có kết quả công bố'}</small></div><span class="list-arrow">›</span></div>`).join('')||'<div class="empty">Chưa có lần khám được duyệt</div>'}${infobox('Lưu nháp kết quả trước khi công bố. Sau khi công bố, bệnh nhân có thể xem trong Hồ sơ sức khỏe.')}`}
function prescriptions(){let ps=db.prescriptions.filter(p=>p.did==='d1');return `${section('Đơn thuốc đã kê','newPrescription','+ Kê đơn')}${ps.map(p=>card(`<b style="font-size:12px">💊 ${pat(p.pid).name}</b><div class="subtle">${p.appointmentId} · ${p.items.length} loại thuốc</div>${p.items.map(i=>kv(esc(i.name),esc(i.dosage))).join('')}${btn('Xem / chỉnh đơn','editPrescription','secondary block',`data-id="${p.appointmentId}"`)}`)).join('')}${btn('+ Tạo đơn thuốc từ lượt khám','newPrescription','block')}${infobox('Màn hình chỉ minh họa thao tác nhập đơn; thông tin liều dùng do bác sĩ chuyên môn quyết định.')}`}
function doctorChat(){return chatScreen('doctor')}
function doctorSchedule(){return `${card(`<div class="page-head"><h2>Lịch làm việc cá nhân</h2><span class="pill-date">11/2026</span></div><div class="week-row">${['T3','T4','T5','T6','T7','CN','T2'].map((d,i)=>`<div class="day-box ${i===0?'active':''}"><small>${d}</small>${17+i}</div>`).join('')}</div>`)}${section('Ca được phân công')}${[['🌞','Ca sáng','08:00 – 11:30'],['🌤️','Ca chiều','13:30 – 17:00']].map(s=>`<div class="list-card"><span class="person-avatar green">${s[0]}</span><div class="person-info"><strong>${s[1]}</strong><small>${s[2]}</small></div>${badge('confirmed')}</div>`).join('')}${section('Đơn xin nghỉ / đổi ca')}${db.leaveRequests.length?db.leaveRequests.map(r=>card(`<b style="font-size:12px">${fmtDate(r.date)}</b> · ${esc(r.reason)}<div style="margin-top:8px">${badge(r.status)}</div>`)).join(''):card('<span class="subtle">Bạn chưa gửi yêu cầu nghỉ hoặc đổi ca.</span>')}${btn('+ Gửi yêu cầu nghỉ / đổi lịch','leaveRequest','block')}${infobox('Yêu cầu được chuyển tới Admin để duyệt; lịch cũ vẫn giữ nguyên tới khi có quyết định.')}`}
function doctorProfile(){let d=doc('d1');return `${card(`<div class="doctor-profile"><div class="avatar-large">${d.emoji}</div><h2>BS. ${d.name}</h2><div class="subtle">${esc(d.specialty)} · ${d.experience} năm kinh nghiệm</div><div class="stars">⭐ ${d.rating} / 5</div></div>`)}${section('Thông tin cá nhân')}${card(`${kv('Số điện thoại',esc(d.phone))}${kv('Chuyên khoa',esc(d.specialty))}${kv('Kinh nghiệm',d.experience+' năm')}${kv('Trạng thái',badge(d.active?'confirmed':'rejected'))}`)}${btn('✏️ Chỉnh sửa hồ sơ','editDoctorProfile','block')}${btn('🔒 Đổi mật khẩu','changePassword','secondary block')}${btn('🚪 Đăng xuất (demo)','demoLogout','outline block')}${infobox('Để đổi chuyên khoa hoặc bằng cấp đã xác minh, cần yêu cầu Admin xử lý.')}`}
// ========= PATIENT · 10 groups =========
function auth(){return `<div class="doctor-profile" style="padding-top:4px"><div class="avatar-large">💙</div><h2>Chào mừng đến với<br>Smart Healthcare</h2><p class="subtle">Bảo vệ sức khỏe của bạn mỗi ngày</p></div>${chips([['login','Đăng nhập'],['register','Đăng ký'],['forgot','Quên mật khẩu']],ui.authMode,'authMode')}<div class="card"><form data-form="auth">${ui.authMode==='register'?formField('Họ và tên','fullname','Nguyễn Văn An','', 'text',true):''}${formField('Email','email','ten@email.com',ui.authMode==='login'?'an.nguyen@gmail.com':'','email',true)}${ui.authMode==='register'?formField('Điện thoại','phone','09xxxxxxxx','', 'tel',true):''}${ui.authMode!=='forgot'?formField('Mật khẩu','password','Ít nhất 6 ký tự','','password',true):''}<button class="button block" type="submit">${ui.authMode==='login'?'Đăng nhập':ui.authMode==='register'?'Đăng ký tài khoản':'Gửi yêu cầu khôi phục'}</button></form></div>${infobox('Đây là bản demo giao diện. Chức năng đăng nhập/xác minh chưa kết nối máy chủ thật.')}`}
function patientHome(){let next=db.appointments.find(a=>a.pid===ui.patient&&['confirmed','pending','proposed'].includes(a.status));return `<div class="hero"><div><span class="hero-badge">SMART HEALTHCARE 💜</span><h2>Xin chào,<br>${esc(pat(ui.patient).name)}!</h2><p>Chủ động chăm sóc sức khỏe của bạn</p></div><span class="hero-icon">👨‍⚕️</span></div><button class="search" style="text-align:left;cursor:pointer" data-action="goSearch">🔍 Tìm bác sĩ, chuyên khoa, bệnh viện...</button><div class="tile-grid">${[['🩺','Tìm bác sĩ','Chọn chuyên khoa','goSearch'],['📅','Đặt lịch khám','Chọn giờ linh hoạt','goBooking'],['📂','Hồ sơ sức khỏe','Lịch sử và đơn thuốc','goRecords'],['💊','Nhắc uống thuốc','Không quên liều','goReminders'],['💬','Chat bác sĩ','Tư vấn từ xa','goPatientChat'],['⭐','Đánh giá','Chia sẻ trải nghiệm','goReviews']].map(x=>`<button class="tile" data-action="${x[3]}"><span class="tile-ico">${x[0]}</span><span class="tile-label">${x[1]}</span><span class="tile-desc">${x[2]}</span></button>`).join('')}</div>${section('Lịch khám sắp tới','goMyAppointments')}${next?apptRow(next):card('<span class="subtle">Bạn chưa có lịch khám. Hãy đặt lịch ngay!</span>')}${section('Bác sĩ nổi bật','goSearch')}${db.doctors.slice(0,2).map(d=>personRow(d,d.specialty+' · ⭐ '+d.rating,'','doctorPublicDetail',d.id)).join('')}`}
function searchDoctors(){let splist=[['Tất cả','Tất cả'],...db.specialties.filter(s=>s.active).map(s=>[s.name,s.name])],arr=db.doctors.filter(d=>(ui.specialty==='Tất cả'||d.specialty===ui.specialty)&&(d.name+' '+d.specialty).toLowerCase().includes(ui.search.toLowerCase())&&d.active);return `<input class="search" placeholder="🔍 Tìm theo tên bác sĩ, chuyên khoa..." value="${esc(ui.search)}" data-search="1">${chips(splist,ui.specialty,'filterSpecialty')}${section(`Kết quả tìm kiếm (${arr.length})`)}${arr.map(d=>`<div class="card"><div class="list-card" style="border:0;padding:0;margin-bottom:9px" data-action="doctorPublicDetail" data-id="${d.id}"><span class="person-avatar">${d.emoji}</span><div class="person-info"><strong>BS. ${esc(d.name)}</strong><small>${esc(d.specialty)} · ${d.experience} năm kinh nghiệm</small><small>⭐ ${d.rating} · Bệnh viện trung tâm</small></div><span class="list-arrow">›</span></div><div class="button-row">${btn('Xem chi tiết','doctorPublicDetail','secondary small',`data-id="${d.id}"`)}${btn('Đặt lịch','bookDoctor','small',`data-id="${d.id}"`)}</div></div>`).join('')||'<div class="empty">Không tìm thấy bác sĩ phù hợp</div>'}`}
function booking(){let d=doc(ui.doctor),steps=['Bác sĩ','Ngày & giờ','Lý do','Xác nhận'];let stepper=`<div class="stepper">${steps.map((s,i)=>`${i?'<span class="step-line"></span>':''}<div class="step ${ui.bookingStep===i+1?'current':ui.bookingStep>i+1?'done':''}"><span>${ui.bookingStep>i+1?'✓':i+1}</span></div>`).join('')}</div><div class="subtle" style="text-align:center;margin-top:-6px;margin-bottom:14px">Bước ${ui.bookingStep}/4 · ${steps[ui.bookingStep-1]}</div>`;let body='';if(ui.bookingStep===1)body=`${section('Chọn bác sĩ')}${db.doctors.filter(d=>d.active).map(d=>`<div class="list-card" data-action="selectDoctor" data-id="${d.id}" style="border-color:${ui.doctor===d.id?'var(--accent)':'#e7edf6'}"><span class="person-avatar">${d.emoji}</span><div class="person-info"><strong>BS. ${esc(d.name)}</strong><small>${esc(d.specialty)} · ⭐ ${d.rating}</small></div>${ui.doctor===d.id?'✅':'○'}</div>`).join('')}`;else if(ui.bookingStep===2)body=`${card(`<b style="font-size:12px">BS. ${esc(d.name)}</b><div class="subtle">${esc(d.specialty)}</div>`)}${section('Chọn ngày khám')}<div class="week-row">${['T3','T4','T5','T6','T7','CN','T2'].map((day,i)=>`<button class="day-box ${ui.date===`2026-11-${String(17+i).padStart(2,'0')}`?'active':''}" data-action="bookDate" data-date="2026-11-${String(17+i).padStart(2,'0')}"><small>${day}</small>${17+i}</button>`).join('')}</div>${section('Chọn khung giờ')}${slotsUI()}`;else if(ui.bookingStep===3)body=`${card(`${kv('Bác sĩ','BS. '+esc(d.name))}${kv('Ngày khám',fmtDate(ui.date))}${kv('Giờ khám',ui.time)}`)}${textarea('Lý do khám','reason',ui.bookingReason,'Ví dụ: Đau đầu, tái khám, khám sức khỏe...')}${infobox('Không nhập thông tin nhạy cảm không cần thiết. Bác sĩ sẽ trao đổi chi tiết trong buổi khám.')}`;else body=`${card(`<div class="doctor-profile"><span class="person-avatar" style="margin:auto;display:grid">${d.emoji}</span><h2>BS. ${esc(d.name)}</h2><p class="subtle">${esc(d.specialty)}</p></div>${kv('Ngày khám',fmtDate(ui.date))}${kv('Giờ khám',ui.time)}${kv('Lý do',esc(ui.bookingReason||'Khám tổng quát'))}${kv('Trạng thái sau gửi',badge('pending'))}`)}${infobox('Gửi yêu cầu không có nghĩa đã được duyệt. Admin sẽ kiểm tra trùng giờ và thông báo kết quả.')}`;return `${stepper}${body}<div class="bottom-fixed"><div class="button-row">${ui.bookingStep>1?btn('← Quay lại','bookingBack','outline'):''}${btn(ui.bookingStep===4?'📨 Gửi yêu cầu':'Tiếp tục →',ui.bookingStep===4?'submitBooking':'bookingNext','block')}</div></div>`}
function slotsUI(){let slots=['08:00','08:30','09:00','09:30','10:00','10:30','13:30','14:00','14:30'];return `<div class="slots">${slots.map(t=>{let unavailable=db.appointments.some(a=>a.did===ui.doctor&&a.date===ui.date&&a.time===t&&['confirmed','inprogress'].includes(a.status))||db.lockedSlots.some(a=>a.did===ui.doctor&&a.date===ui.date&&a.time===t);return `<button class="slot ${ui.time===t?'selected':''} ${unavailable?'booked':''}" data-action="bookTime" data-time="${t}" ${unavailable?'disabled':''}>${t}</button>`}).join('')}</div><div class="subtle">Khung giờ đã xác nhận sẽ bị khóa khi đặt lịch</div>`}
function myAppointments(){let arr=db.appointments.filter(a=>a.pid===ui.patient),available=[['all','Tất cả'],['pending','Chờ duyệt'],['confirmed','Đã duyệt'],['proposed','Đổi giờ'],['completed','Đã khám'],['cancelled','Đã hủy']];return `${chips(available,ui.filter,'filter')}${arr.filter(a=>ui.filter==='all'||a.status===ui.filter).map(a=>apptRow(a)).join('')||'<div class="empty">Không có lịch khám phù hợp</div>'}${btn('+ Đặt lịch khám mới','goBooking','block')}`}
function patientChat(){return chatScreen('patient')}
function chatScreen(role){return `<div class="list-card"><span class="person-avatar">${role==='patient'?doc('d1').emoji:pat('p1').emoji}</span><div class="person-info"><strong>${role==='patient'?'BS. Trần Minh Đức':'Nguyễn Văn An'}</strong><small>🟢 Đang hoạt động · Tư vấn sức khỏe</small></div><span class="list-arrow">⋮</span></div><div class="chat-area">${db.messages.map(m=>`<div class="bubble ${m.role===role?'me':''}">${esc(m.text)}<small>${esc(m.time)}</small></div>`).join('')}</div><form class="chat-compose" data-form="chat"><input name="message" required placeholder="Nhập tin nhắn..." autocomplete="off"><button type="submit" class="button">➤</button></form><div class="subtle" style="text-align:center;margin-top:6px">Mô phỏng hội thoại · Không gửi tin thật</div>`}
function records(){let rr=db.results.filter(r=>r.pid===ui.patient&&r.published);return `${section('Lịch sử thăm khám')}${rr.map(r=>`<div class="card" data-action="recordDetail" data-id="${r.appointmentId}" style="cursor:pointer"><div class="page-head"><h2>🩺 ${esc(r.diagnosis)}</h2>${badge('completed')}</div>${kv('Bác sĩ','BS. '+doc(r.did).name)}${kv('Mã lượt khám',r.appointmentId)}${kv('Ngày khám',fmtDate(db.appointments.find(a=>a.id===r.appointmentId)?.date))}<div class="button-row">${btn('Xem kết quả','recordDetail','secondary small',`data-id="${r.appointmentId}"`)}${btn('Xem đơn thuốc','recordPrescription','small',`data-id="${r.appointmentId}"`)}</div></div>`).join('')||'<div class="empty">Chưa có kết quả khám công bố</div>'}${infobox('Bệnh nhân chỉ được xem kết quả do bác sĩ đã công bố, không sửa nội dung chuyên môn.')}`}
function reminders(){return `${section('Nhắc uống thuốc','addReminder','+ Thêm')}${db.medications.map(m=>`<div class="card"><div class="page-head"><h2>💊 ${esc(m.name)}</h2><input type="checkbox" class="switch" data-switch="reminder" data-id="${m.id}" ${m.active?'checked':''}></div><p class="subtle" style="margin:0 0 9px">${esc(m.dosage)}</p><div class="chip-row">${m.times.map(t=>`<span class="chip">⏰ ${t}</span>`).join('')}</div><div class="button-row"><button class="button ${m.taken?'green':'secondary'} small" data-action="toggleTaken" data-id="${m.id}">${m.taken?'✓ Đã uống':'☐ Đánh dấu đã uống'}</button>${btn('Sửa','editReminder','outline small',`data-id="${m.id}"`)}</div></div>`).join('')}${btn('+ Tạo lời nhắc thuốc','addReminder','block')}${infobox('Nhắc thuốc chỉ hỗ trợ ghi nhớ; không thay đổi liều dùng đã được bác sĩ kê.')}`}
function reviews(){let completed=db.appointments.filter(a=>a.pid===ui.patient&&a.status==='completed');return `${section('Đánh giá bác sĩ sau khám')}${completed.map(a=>`<div class="list-card" data-action="newReview" data-id="${a.id}"><span class="person-avatar">${doc(a.did).emoji}</span><div class="person-info"><strong>BS. ${doc(a.did).name}</strong><small>Hoàn thành: ${fmtDate(a.date)}</small><small>${db.reviews.some(r=>r.appt===a.id)?'⭐ Đã đánh giá':'Chạm để đánh giá'}</small></div><span class="list-arrow">›</span></div>`).join('')||'<div class="empty">Chưa có lịch hoàn thành để đánh giá</div>'}${section('Phản hồi dịch vụ')}${card(`${textarea('Bạn có góp ý gì?','feedback','','Chất lượng dịch vụ, trải nghiệm đặt khám...')}${btn('Gửi phản hồi','sendFeedback','block')}`)}`}
function settings(){let p=pat(ui.patient);return `${card(`<div class="list-card" style="padding:3px;border:0"><span class="person-avatar">${p.emoji}</span><div class="person-info"><strong>${esc(p.name)}</strong><small>${esc(p.email)}</small><small>Mã bệnh nhân: ${p.id.toUpperCase()}</small></div><span class="list-arrow">›</span></div>${selectField('Chuyển bệnh nhân demo để kiểm tra lịch trùng','demoPatient',db.patients.map(x=>[x.id,x.name]),ui.patient)}`)}${section('Thông báo mới')}${db.notifications.filter(n=>n.role==='patient'||n.role==='all').slice(-4).reverse().map(n=>`<div class="list-card"><span class="person-avatar">🔔</span><div class="person-info"><strong>${esc(n.text)}</strong><small>${n.date}</small></div></div>`).join('')}${section('Tùy chỉnh tài khoản')}${[['👤','Chỉnh sửa hồ sơ','editPatientProfile'],['🔒','Đổi mật khẩu','changePassword'],['🔔','Cài đặt thông báo','notificationToggles'],['🚪','Đăng xuất','demoLogout']].map(x=>`<div class="list-card" data-action="${x[2]}"><span class="person-avatar">${x[0]}</span><div class="person-info"><strong>${x[1]}</strong></div><span class="list-arrow">›</span></div>`).join('')}`}
// ========= Interactive sub-screens, modals and actions =========
function appointmentDetail(id){const a=db.appointments.find(a=>a.id===id);if(!a)return;ui.selectedAppt=id;let d=doc(a.did),p=pat(a.pid);let body=`${card(`<div class="page-head"><h2>${esc(p.name)}</h2>${badge(a.status)}</div>${kv('Mã lịch',a.id)}${kv('Bác sĩ','BS. '+esc(d.name))}${kv('Chuyên khoa',esc(d.specialty))}${kv('Ngày khám',fmtDate(a.date))}${kv('Thời gian',a.time)}${kv('Lý do',esc(a.reason))}${a.proposedTime?kv('Giờ đề xuất mới',a.proposedTime):''}`)}`;
 if(ui.role==='admin'&&a.status==='pending'){let conflict=db.appointments.filter(x=>x.id!==a.id&&x.did===a.did&&x.date===a.date&&x.time===a.time&&['confirmed','inprogress'].includes(x.status)).length;body+=conflict?infobox(`Khung ${a.time} đã được xác nhận cho ${conflict} người. Không thể duyệt thêm nếu sức chứa là 1.`,'warn'):infobox('Khung giờ hiện chưa có lịch đã duyệt. Nếu có nhiều yêu cầu cùng giờ, chỉ chọn một.', '');body+=`<div class="button-row">${btn('✓ Xác nhận','approveAppt','green',`data-id="${a.id}"`)}${btn('✕ Từ chối','rejectAppt','danger',`data-id="${a.id}"`)}</div><div class="button-row">${btn('🔄 Đề xuất giờ khác','proposeAppt','secondary block',`data-id="${a.id}"`)}</div>`}
 if(ui.role==='doctor'&&['confirmed','inprogress'].includes(a.status)){body+=`<div class="button-row">${a.status==='confirmed'?btn('✓ Bệnh nhân đã đến','checkInAppt','secondary',`data-id="${a.id}"`):''}${btn('🩺 '+(a.status==='inprogress'?'Ghi kết quả khám':'Bắt đầu khám'),'startExam','green',`data-id="${a.id}"`)}</div>`}
 if(ui.role==='patient'){if(a.status==='pending'||a.status==='confirmed')body+=btn('✕ Hủy yêu cầu','cancelAppt','danger block',`data-id="${a.id}"`);if(a.status==='proposed')body+=`<div class="button-row">${btn('✓ Đồng ý giờ mới','acceptProposal','green',`data-id="${a.id}"`)}${btn('Không đồng ý','rejectProposal','danger',`data-id="${a.id}"`)}</div>`;if(a.status==='completed')body+=btn('⭐ Đánh giá bác sĩ','newReview','block',`data-id="${a.id}"`)}openModal('Chi tiết lịch khám',body)
}
function conflictModal(){let conflict=db.appointments.filter(a=>a.did==='d1'&&a.date===nowDate&&a.time==='08:30'&&['pending','confirmed'].includes(a.status));let existing=conflict.filter(a=>a.status==='confirmed').length;openModal('⚠️ Xử lý trùng lịch',`${infobox(`<b>${conflict.length} yêu cầu</b> cùng giờ 08:30 ngày 17/11/2026 với BS. Trần Minh Đức. <b>Sức chứa ca: 1</b>.`,'warn')}${conflict.map(a=>`<div class="list-card"><span class="person-avatar">${pat(a.pid).emoji}</span><div class="person-info"><strong>${pat(a.pid).name}</strong><small>${a.id} · ${a.reason}</small></div>${badge(a.status)}</div>`).join('')}${existing?infobox('Đã có 1 lịch được duyệt. Các yêu cầu còn lại phải đổi giờ hoặc từ chối.','warn'):infobox('Chọn duyệt 1 lịch. Hệ thống sẽ tự khóa giờ đó và giữ các yêu cầu khác chờ xử lý.','')}<div class="button-row">${btn('Quay lại','closeModal','outline')}${btn('Xem yêu cầu','closeToApprovals','secondary')}</div>`)}
function doctorDetail(id){let d=doc(id);openModal('Thông tin bác sĩ',`${card(`<div class="doctor-profile"><div class="avatar-large">${d.emoji}</div><h2>BS. ${esc(d.name)}</h2><p class="subtle">${esc(d.specialty)}</p><div class="stars">⭐ ${d.rating} · ${d.experience} năm kinh nghiệm</div></div>${kv('Điện thoại',esc(d.phone))}${kv('Tài khoản',d.active?'Hoạt động':'Đã khóa')}${kv('Lịch đã đặt',db.appointments.filter(a=>a.did===id).length+' lịch')}`)}<div class="button-row">${btn('Sửa thông tin','openDoctorForm','secondary',`data-id="${id}"`)}${btn(d.active?'Khóa tài khoản':'Mở khóa','toggleDoctor','danger',`data-id="${id}"`)}</div>`)}
function doctorForm(id){let d=id?doc(id):{};openModal(d.id?'Sửa bác sĩ':'Thêm bác sĩ',`<form data-form="doctor" data-id="${d.id||''}">${formField('Họ tên bác sĩ','name','Nguyễn Văn A',d.name||'','text',true)}${selectField('Chuyên khoa','specialty',db.specialties.map(s=>[s.name,s.name]),d.specialty||db.specialties[0].name)}${formField('Số điện thoại','phone','09xxxxxxxx',d.phone||'','tel',true)}${formField('Số năm kinh nghiệm','experience','5',d.experience||5,'number',true)}<button class="button block" type="submit">Lưu thông tin</button></form>`)}
function patientDetail(id,doctorView=false){let p=pat(id);ui.selectedPatient=id;let items=db.appointments.filter(a=>a.pid===id&&(doctorView?a.did==='d1':true));openModal(doctorView?'Hồ sơ bệnh nhân':'Chi tiết bệnh nhân',`${card(`${personRow(p,`${p.age} tuổi`,badge(p.active?'confirmed':'rejected'))}${kv('Số điện thoại',p.phone)}${kv('Email',p.email)}${kv('Lịch liên quan',items.length+' lần')}`)}${section('Lịch sử đặt khám')}${items.map(a=>`<div class="card" style="font-size:11px">${a.id} · ${fmtDate(a.date)} ${a.time}<div style="margin-top:6px">${badge(a.status)}</div></div>`).join('')}${!doctorView?btn(p.active?'Khóa tài khoản':'Mở tài khoản','togglePatient','danger block',`data-id="${id}"`):btn('Xem kết quả khám','goExam','secondary block')}`)}
function doctorPublicDetail(id){let d=doc(id);ui.doctor=id;openModal('Chi tiết bác sĩ',`${card(`<div class="doctor-profile"><div class="avatar-large">${d.emoji}</div><h2>BS. ${esc(d.name)}</h2><div class="subtle">${esc(d.specialty)} · 12 năm kinh nghiệm</div><div class="stars">⭐ ${d.rating} (256 đánh giá)</div></div>${kv('Nơi làm việc','Bệnh viện Trung tâm')}${kv('Chuyên khoa',d.specialty)}${kv('Giờ khám','08:00 – 11:30 / 13:30 – 17:00')}`)}${section('Khung giờ còn trống')}${slotsUI()}${btn('📅 Đặt lịch với bác sĩ này','bookDoctor','block',`data-id="${id}"`)}`)}
function specialtyDetail(id){let s=db.specialties.find(x=>x.id===id);openModal('Chi tiết chuyên khoa',`${card(`<b>${s.icon} ${s.name}</b>${kv('Trạng thái',s.active?'Hiển thị':'Đã ẩn')}${kv('Số bác sĩ',db.doctors.filter(d=>d.specialty===s.name).length)}`)}<div class="button-row">${btn('Sửa tên','openSpecialtyForm','secondary',`data-id="${id}"`)}${btn(s.active?'Ẩn chuyên khoa':'Hiển thị','toggleSpecialty','outline',`data-id="${id}"`)}</div>`)}
function editResult(appointmentId){let a=db.appointments.find(x=>x.id===appointmentId),r=db.results.find(x=>x.appointmentId===appointmentId)||{};if(!a)return;openModal('🩺 Phiên khám & kết quả',`${card(`${kv('Bệnh nhân',pat(a.pid).name)}${kv('Ngày / giờ',fmtDate(a.date)+' · '+a.time)}${kv('Lý do',esc(a.reason))}`)}<form data-form="exam" data-id="${appointmentId}">${textarea('Triệu chứng / Chẩn đoán','diagnosis',r.diagnosis||'','Nhập chẩn đoán sau khám')}${textarea('Hướng điều trị','treatment',r.treatment||'','Nhập hướng điều trị')}${textarea('Lời dặn','advice',r.advice||'','Lời dặn bệnh nhân')}<div class="button-row"><button class="button secondary" name="mode" value="draft" type="submit">Lưu nháp</button><button class="button green" name="mode" value="publish" type="submit">Hoàn tất & công bố</button></div></form>${r.published?infobox('Kết quả này đã được công bố cho bệnh nhân.','success'):''}`)}
function prescriptionForm(apptId){let list=db.appointments.filter(a=>a.did==='d1'&&['confirmed','inprogress','completed'].includes(a.status)),a=list.find(x=>x.id===apptId)||list[0];if(!a){toast('Chưa có lịch khám hợp lệ để kê đơn');return}let pres=db.prescriptions.find(p=>p.appointmentId===a.id),item=pres?.items[0]||{};openModal('💊 Soạn đơn thuốc',`<form data-form="prescription" data-id="${a.id}">${card(`${kv('Bệnh nhân',pat(a.pid).name)}${kv('Mã lượt khám',a.id)}`)}${formField('Tên thuốc','medicine','Tên thuốc',item.name||'','text',true)}${formField('Liều lượng và cách dùng','dosage','Theo chỉ định của bác sĩ',item.dosage||'','text',true)}${formField('Số ngày dùng','days','3',item.days||3,'number',true)}${textarea('Ghi chú','note',pres?.note||'','Lưu ý khi dùng thuốc')}<button class="button block" type="submit">💾 Lưu đơn thuốc</button></form>${infobox('Đây là form demo. Không sử dụng thông tin minh họa để tự điều trị.')}`)}
function reminderForm(id){let m=db.medications.find(x=>x.id===id)||{name:'',dosage:'',times:['08:00'],active:true};openModal(id?'Sửa nhắc thuốc':'Tạo nhắc thuốc',`<form data-form="reminder" data-id="${id||''}">${formField('Tên thuốc','name','Tên thuốc theo đơn',m.name,'text',true)}${formField('Liều dùng (theo đơn bác sĩ)','dosage','VD: 1 viên mỗi lần',m.dosage,'text',true)}${formField('Các giờ nhắc (ngăn cách bằng dấu phẩy)','times','08:00, 20:00',m.times.join(', '),'text',true)}<button class="button block" type="submit">Lưu lời nhắc</button></form>`)}
function newReview(id){let a=db.appointments.find(x=>x.id===id);let previous=db.reviews.find(x=>x.appt===id);if(previous){toast('Bạn đã đánh giá lần khám này');return}ui.selectedAppt=id;ui.rating=5;openModal('⭐ Đánh giá sau khám',`${card(`<b style="font-size:12px">BS. ${doc(a.did).name}</b><div class="subtle">Lịch hoàn thành ngày ${fmtDate(a.date)}</div>`)}<div id="ratingStars" class="rating">${Array.from({length:5},(_,i)=>`<button class="on" data-action="rate" data-rating="${i+1}">★</button>`).join('')}</div><form data-form="review">${textarea('Nhận xét của bạn','comment','','Bạn đánh giá thế nào về trải nghiệm?')}<button type="submit" class="button block">Gửi đánh giá</button></form>`)}
function showChangePassword(){openModal('Đổi mật khẩu',`<form data-form="password">${formField('Mật khẩu hiện tại','current','','','password',true)}${formField('Mật khẩu mới','password','Ít nhất 6 ký tự','','password',true)}<button type="submit" class="button block">Cập nhật (demo)</button></form>`)}
function profileForm(role){let x=role==='doctor'?doc('d1'):pat(ui.patient);openModal('Chỉnh sửa hồ sơ',`<form data-form="profile">${formField('Họ và tên','name','Họ tên',x.name,'text',true)}${formField('Số điện thoại','phone','09xxxxxxxx',x.phone,'tel',true)}${role==='patient'?formField('Email','email','Email',x.email,'email',true):''}<button type="submit" class="button block">Lưu thay đổi</button></form>`)}
function addNotice(message,role='patient'){db.notifications.push({text:message,role,date:fmtDate(nowDate)});save()}
function validateApprove(id){let a=db.appointments.find(x=>x.id===id);if(!a||a.status!=='pending')return;let used=db.appointments.some(x=>x.id!==id&&x.did===a.did&&x.date===a.date&&x.time===a.time&&['confirmed','inprogress'].includes(x.status));if(used){closeModal();openModal('Không thể xác nhận',`${infobox('Khung giờ '+a.time+' của BS. '+doc(a.did).name+' đã được duyệt cho bệnh nhân khác. Sức chứa ca là 1. Hãy đề xuất giờ khác.','warn')}${btn('🔄 Đề xuất giờ mới','proposeAppt','block',`data-id="${id}"`)}`);return}a.status='confirmed';addNotice(`Lịch ${a.id} lúc ${a.time} đã được Admin xác nhận`);closeModal();save();render();toast('Đã duyệt lịch '+id+' · giờ được khóa cho lượt khác')}
function proposeModal(id){let a=db.appointments.find(x=>x.id===id);openModal('Đề xuất giờ khám khác',`${card(`${kv('Bệnh nhân',pat(a.pid).name)}${kv('Giờ đã yêu cầu',a.time+' · '+fmtDate(a.date))}`)}<form data-form="proposal" data-id="${id}">${selectField('Giờ khám mới','time',['09:00','09:30','10:00','10:30','14:00','14:30','15:00'].map(t=>[t,t]),'09:00')}${textarea('Ghi chú cho bệnh nhân','note','','Khung giờ cũ đã có người đặt')}<button type="submit" class="button block">Gửi đề xuất cho bệnh nhân</button></form>`)}
function exportCSV(){let content='Mã lịch,Bệnh nhân,Bác sĩ,Ngày,Giờ,Trạng thái\n'+db.appointments.map(a=>[a.id,pat(a.pid).name,doc(a.did).name,a.date,a.time,a.status].map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n');let blob=new Blob(['\ufeff'+content],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='smart-healthcare-bao-cao.csv';a.click();URL.revokeObjectURL(url);toast('Đã xuất CSV dữ liệu demo')}
const quickGo={goDoctors:'doctors',goPatients:'patients',goApprovals:'approvals',goReports:'reports',goDoctorAppointments:'doctorAppointments',goAssignedPatients:'assignedPatients',goExam:'exam',goPrescriptions:'prescriptions',goDoctorChat:'doctorChat',goDoctorSchedule:'doctorSchedule',goSearch:'searchDoctors',goBooking:'booking',goRecords:'records',goReminders:'reminders',goPatientChat:'patientChat',goReviews:'reviews',goMyAppointments:'myAppointments'};
document.addEventListener('click',e=>{let el=e.target.closest('[data-action]');if(!el)return;let act=el.dataset.action,id=el.dataset.id,value=el.dataset.value;
 if(act==='go'){go(el.dataset.page);return}if(quickGo[act]){go(quickGo[act]);return}if(act==='role'){setRole(el.dataset.role);return}if(act==='drawer'){if(el.classList.contains('drawer-backdrop')&&e.target!==el)return;ui.drawer=!ui.drawer;renderShell();return}if(act==='closeModal'){if(el.classList.contains('modal-backdrop')&&e.target!==el)return;closeModal();return}
 if(act==='reset'){if(window.confirm('Đặt lại toàn bộ dữ liệu demo về ban đầu?')){db=JSON.parse(JSON.stringify(seed));save();ui.drawer=false;render();toast('Đã đặt lại dữ liệu minh họa')}return}
 if(act==='filter'){ui.filter=value;render();return}if(act==='authMode'){ui.authMode=value;render();return}if(act==='filterSpecialty'){ui.specialty=value;render();return}
 if(act==='apptDetail'){appointmentDetail(id);return}if(act==='showConflict'){conflictModal();return}if(act==='closeToApprovals'){go('approvals');return}
 if(act==='approveAppt'){validateApprove(id);return}if(act==='rejectAppt'){let a=db.appointments.find(x=>x.id===id);if(a){a.status='rejected';addNotice(`Lịch ${a.id} không được chấp nhận. Bạn có thể đặt lịch khác.`);closeModal();render();toast('Đã từ chối '+id)}return}
 if(act==='proposeAppt'){proposeModal(id);return}
 if(act==='cancelAppt'){let a=db.appointments.find(x=>x.id===id);if(a&&window.confirm('Bạn muốn hủy lịch khám này?')){a.status='cancelled';addNotice(`Bạn đã hủy lịch ${id}`);closeModal();render();toast('Đã hủy lịch khám')}return}
 if(act==='acceptProposal'){let a=db.appointments.find(x=>x.id===id);if(!a)return;let used=db.appointments.some(x=>x.id!==a.id&&x.did===a.did&&x.date===a.date&&x.time===a.proposedTime&&['confirmed','inprogress'].includes(x.status));if(used){toast('Giờ đề xuất đã kín. Vui lòng liên hệ Admin');return}a.time=a.proposedTime;a.proposedTime='';a.status='confirmed';addNotice(`Bạn đã đồng ý chuyển lịch ${id} sang ${a.time}`);closeModal();render();toast('Đã xác nhận giờ khám mới');return}
 if(act==='rejectProposal'){let a=db.appointments.find(x=>x.id===id);if(a){a.status='cancelled';closeModal();render();toast('Đã từ chối giờ thay thế')}return}
 if(act==='doctorDetail'){doctorDetail(id);return}if(act==='openDoctorForm'){doctorForm(id);return}if(act==='toggleDoctor'){let d=doc(id);d.active=!d.active;save();closeModal();render();toast('Đã cập nhật trạng thái bác sĩ');return}
 if(act==='patientDetail'){patientDetail(id);return}if(act==='doctorPatientDetail'){patientDetail(id,true);return}if(act==='togglePatient'){let p=pat(id);p.active=!p.active;save();closeModal();render();toast('Đã cập nhật trạng thái bệnh nhân');return}
 if(act==='workDay'){ui.workDate=el.dataset.date;render();return}if(act==='toggleSlot'){let time=el.dataset.time,existing=db.lockedSlots.findIndex(x=>x.date===ui.workDate&&x.time===time&&x.did===ui.doctor),used=db.appointments.some(x=>x.did===ui.doctor&&x.date===ui.workDate&&x.time===time&&x.status==='confirmed');if(used){toast('Ca đang có lịch đã xác nhận. Cần đổi lịch trước.');return}if(existing>=0)db.lockedSlots.splice(existing,1);else db.lockedSlots.push({did:ui.doctor,date:ui.workDate,time});save();render();return}
 if(act==='approveLeave'||act==='rejectLeave'){let req=db.leaveRequests[Number(id)];if(req){req.status=act==='approveLeave'?'confirmed':'rejected';addNotice('Yêu cầu nghỉ / đổi ca đã được '+(req.status==='confirmed'?'chấp thuận':'từ chối'),'doctor');save();render();toast('Đã xử lý yêu cầu của bác sĩ')}return}
 if(act==='newWorkShift'){openModal('Tạo / điều chỉnh ca làm việc',`<form data-form="shift">${selectField('Bác sĩ','did',db.doctors.map(d=>[d.id,'BS. '+d.name]),ui.doctor)}${formField('Ngày','date','',ui.workDate,'date',true)}${selectField('Ca làm việc','shift',[['morning','Ca sáng 08:00–11:30'],['afternoon','Ca chiều 13:30–17:00']],'morning')}<button type="submit" class="button block">Tạo ca làm việc</button></form>`);return}
 if(act==='specialtyDetail'){specialtyDetail(id);return}if(act==='openSpecialtyForm'){let s=db.specialties.find(x=>x.id===id)||{name:'',icon:'🩺'};openModal(id?'Sửa chuyên khoa':'Thêm chuyên khoa',`<form data-form="specialty" data-id="${id||''}">${formField('Tên chuyên khoa','name','Ví dụ: Nội tiết',s.name,'text',true)}${formField('Biểu tượng','icon','🩺',s.icon)}<button type="submit" class="button block">Lưu chuyên khoa</button></form>`);return}if(act==='toggleSpecialty'){let s=db.specialties.find(x=>x.id===id);s.active=!s.active;save();closeModal();render();toast('Đã cập nhật chuyên khoa');return}
 if(act==='composeNotification'){openModal('📨 Soạn thông báo',`<form data-form="notification">${selectField('Đối tượng nhận','role',[['all','Tất cả tài khoản'],['doctor','Bác sĩ'],['patient','Bệnh nhân']],'all')}${textarea('Nội dung thông báo','message','','Ví dụ: Hệ thống bảo trì lúc...')}<button type="submit" class="button block">Gửi thông báo (demo)</button></form>`);return}if(act==='exportReport'){exportCSV();return}
 if(act==='checkInAppt'){toast('Đã ghi nhận bệnh nhân đến khám');return}if(act==='startExam'){let a=db.appointments.find(x=>x.id===id);a.status='inprogress';save();editResult(id);return}if(act==='editExam'){editResult(id);return}if(act==='newPrescription'){prescriptionForm('');return}if(act==='editPrescription'){prescriptionForm(id);return}
 if(act==='leaveRequest'){openModal('📅 Xin nghỉ / đổi ca',`<form data-form="leave">${formField('Ngày đề nghị','date','',nowDate,'date',true)}${selectField('Loại yêu cầu','type',[['leave','Xin nghỉ'],['shift','Đổi ca']],'leave')}${textarea('Lý do','reason','','Nhập lý do đề nghị')}<button type="submit" class="button block">Gửi Admin duyệt</button></form>`);return}
 if(act==='editDoctorProfile'){profileForm('doctor');return}if(act==='editPatientProfile'){profileForm('patient');return}if(act==='changePassword'){showChangePassword();return}if(act==='demoLogout'){go(ui.role==='patient'?'auth':ui.role==='doctor'?'doctorHome':'dashboard');toast('Đã trở về màn hình demo');return}
 if(act==='doctorPublicDetail'){doctorPublicDetail(id);return}if(act==='bookDoctor'){ui.doctor=id;ui.bookingStep=2;ui.time='08:30';go('booking');return}if(act==='selectDoctor'){ui.doctor=id;render();return}if(act==='bookDate'){ui.date=el.dataset.date;render();return}if(act==='bookTime'){ui.time=el.dataset.time;render();return}
 if(act==='bookingNext'){if(ui.bookingStep===3){let f=$('#appContent [name="reason"]');ui.bookingReason=f?.value||'Khám tổng quát'}ui.bookingStep=Math.min(ui.bookingStep+1,4);render();return}if(act==='bookingBack'){ui.bookingStep=Math.max(1,ui.bookingStep-1);render();return}
 if(act==='submitBooking'){if(!db.doctors.some(d=>d.id===ui.doctor)){toast('Vui lòng chọn bác sĩ');return}let id='K'+String(Math.max(5,...db.appointments.map(a=>parseInt(a.id.slice(1))||0))+1).padStart(3,'0');db.appointments.push({id,pid:ui.patient,did:ui.doctor,date:ui.date,time:ui.time,reason:ui.bookingReason||'Khám tổng quát',status:'pending'});addNotice(`Đã gửi yêu cầu ${id}. Trạng thái: CHỜ DUYỆT`);ui.bookingStep=1;ui.filter='all';go('myAppointments');toast('Đã gửi yêu cầu · đang chờ Admin duyệt');return}
 if(act==='recordDetail'){let r=db.results.find(x=>x.appointmentId===id);if(!r)return;openModal('Kết quả khám',`${card(`${kv('Ngày khám',fmtDate(db.appointments.find(a=>a.id===id)?.date))}${kv('Chẩn đoán',esc(r.diagnosis))}${kv('Hướng điều trị',esc(r.treatment))}${kv('Lời dặn',esc(r.advice))}${kv('Bác sĩ',doc(r.did).name)}`)}${btn('Xem đơn thuốc','recordPrescription','block',`data-id="${id}"`)}`);return}
 if(act==='recordPrescription'){let p=db.prescriptions.find(x=>x.appointmentId===id);openModal('Đơn thuốc đã kê',p?`${card(`${p.items.map(x=>`${kv('Thuốc',esc(x.name))}${kv('Cách dùng',esc(x.dosage))}${kv('Số ngày',esc(x.days)+' ngày')}`).join('')}`)}${btn('Tạo nhắc uống thuốc','goReminders','block')}`:infobox('Lần khám này chưa có đơn thuốc công bố'));return}
 if(act==='addReminder'){reminderForm('');return}if(act==='editReminder'){reminderForm(id);return}if(act==='toggleTaken'){let m=db.medications.find(x=>x.id===id);m.taken=!m.taken;save();render();return}
 if(act==='newReview'){newReview(id);return}if(act==='rate'){ui.rating=Number(el.dataset.rating);let stars=$('#ratingStars');if(stars)stars.innerHTML=Array.from({length:5},(_,i)=>`<button class="${i<ui.rating?'on':''}" data-action="rate" data-rating="${i+1}">★</button>`).join('');return}
 if(act==='notificationToggles'){openModal('Cài đặt thông báo',card(['Thông báo lịch khám','Đề xuất đổi giờ','Nhắc thuốc','Tin nhắn bác sĩ'].map(x=>`<div class="toggle-row">${x}<input type="checkbox" class="switch" checked></div>`).join('')));return}
 if(act==='sendFeedback'){let t=$('#appContent textarea[name="feedback"]');if(!t?.value.trim()){toast('Vui lòng nhập phản hồi');return}t.value='';toast('Đã tiếp nhận phản hồi minh họa');return}
});
document.addEventListener('input',e=>{if(e.target.dataset.search){let input=e.target;ui.search=input.value;let cursor=input.selectionStart;let scroll=$('#appContent').scrollTop;$('#appContent').innerHTML=pageContent();let refreshed=$('#appContent [data-search]');if(refreshed){refreshed.focus();refreshed.setSelectionRange(cursor,cursor)}$('#appContent').scrollTop=scroll}});
document.addEventListener('change',e=>{if(e.target.name==='scheduleDoctor'){ui.doctor=e.target.value;render()}if(e.target.name==='demoPatient'){ui.patient=e.target.value;ui.filter='all';render();toast('Đã chuyển tài khoản bệnh nhân demo')}if(e.target.dataset.switch==='reminder'){let m=db.medications.find(x=>x.id===e.target.dataset.id);m.active=e.target.checked;save();toast('Đã cập nhật trạng thái nhắc thuốc')}});
document.addEventListener('submit',e=>{let form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();let vals=Object.fromEntries(new FormData(form).entries()),type=form.dataset.form,id=form.dataset.id;
 if(type==='auth'){if(ui.authMode==='register'){toast('Tạo tài khoản demo thành công · đã gửi mã xác minh (minh họa)');ui.authMode='login';render()}else if(ui.authMode==='forgot'){toast('Đã mô phỏng gửi email khôi phục');ui.authMode='login';render()}else{go('patientHome');toast('Đăng nhập thành công (chế độ demo)')}return}
 if(type==='doctor'){let d=id?doc(id):null;if(d){Object.assign(d,{name:vals.name,specialty:vals.specialty,phone:vals.phone,experience:Number(vals.experience)})}else{db.doctors.push({id:'d'+(db.doctors.length+1),name:vals.name,specialty:vals.specialty,phone:vals.phone,experience:Number(vals.experience),rating:5,emoji:'👨🏻‍⚕️',active:true})}save();closeModal();render();toast('Đã lưu thông tin bác sĩ');return}
 if(type==='specialty'){let s=db.specialties.find(x=>x.id===id);if(s){s.name=vals.name;s.icon=vals.icon}else db.specialties.push({id:'s'+(db.specialties.length+1),name:vals.name,icon:vals.icon,active:true});save();closeModal();render();toast('Đã lưu chuyên khoa');return}
 if(type==='shift'){ui.doctor=vals.did;ui.workDate=vals.date;closeModal();render();toast('Đã tạo ca demo; bạn có thể khóa/mở từng khung giờ');return}
 if(type==='notification'){if(!vals.message?.trim())return toast('Nhập nội dung trước khi gửi');addNotice(vals.message,vals.role);closeModal();render();toast('Đã gửi thông báo demo');return}
 if(type==='proposal'){let a=db.appointments.find(x=>x.id===id);let occupied=db.appointments.some(x=>x.id!==id&&x.did===a.did&&x.date===a.date&&x.time===vals.time&&['confirmed','inprogress'].includes(x.status));if(occupied)return toast('Giờ mới đã có lịch xác nhận, hãy chọn giờ khác');a.proposedTime=vals.time;a.status='proposed';addNotice(`Admin đề xuất đổi lịch ${id} sang ${vals.time}. Bạn hãy xác nhận.`);closeModal();render();toast('Đã gửi đề xuất giờ mới cho bệnh nhân');return}
 if(type==='exam'){let a=db.appointments.find(x=>x.id===id),r=db.results.find(x=>x.appointmentId===id),publish=e.submitter?.value==='publish';if(!vals.diagnosis.trim())return toast('Vui lòng nhập chẩn đoán');if(!r){r={appointmentId:id,pid:a.pid,did:a.did};db.results.push(r)}Object.assign(r,{diagnosis:vals.diagnosis,treatment:vals.treatment,advice:vals.advice,published:publish});if(publish){a.status='completed';addNotice(`Kết quả khám ${id} đã được bác sĩ công bố`)}save();closeModal();render();toast(publish?'Đã hoàn tất buổi khám & công bố kết quả':'Đã lưu nháp kết quả');return}
 if(type==='prescription'){let a=db.appointments.find(x=>x.id===id),p=db.prescriptions.find(x=>x.appointmentId===id);if(!p){p={appointmentId:id,pid:a.pid,did:a.did,items:[]};db.prescriptions.push(p)}p.items=[{name:vals.medicine,dosage:vals.dosage,days:vals.days}];p.note=vals.note||'';addNotice(`Bác sĩ đã cập nhật đơn thuốc cho lượt khám ${id}`);save();closeModal();render();toast('Đã lưu đơn thuốc điện tử');return}
 if(type==='leave'){db.leaveRequests.push({date:vals.date,type:vals.type,reason:vals.reason||'Chưa có lý do',status:'pending'});save();closeModal();render();toast('Đã gửi yêu cầu để Admin duyệt');return}
 if(type==='reminder'){let m=db.medications.find(x=>x.id===id);let data={name:vals.name,dosage:vals.dosage,times:vals.times.split(',').map(x=>x.trim()).filter(Boolean),active:true,taken:false};if(m)Object.assign(m,data);else db.medications.push({id:'m'+(db.medications.length+1),...data});save();closeModal();render();toast('Đã lưu nhắc thuốc');return}
 if(type==='review'){db.reviews.push({appt:ui.selectedAppt,rating:ui.rating,comment:vals.comment});save();closeModal();render();toast('Cảm ơn bạn đã đánh giá!');return}
 if(type==='password'){if(vals.password.length<6)return toast('Mật khẩu mới phải từ 6 ký tự');closeModal();toast('Đã mô phỏng đổi mật khẩu');return}
 if(type==='profile'){let x=ui.role==='doctor'?doc('d1'):pat(ui.patient);x.name=vals.name;x.phone=vals.phone;if(vals.email)x.email=vals.email;save();closeModal();render();toast('Đã lưu hồ sơ cá nhân');return}
 if(type==='chat'){let v=vals.message?.trim();if(!v)return;db.messages.push({role:ui.role==='doctor'?'doctor':'patient',text:v,time:'09:41'});save();render();$('#appContent').scrollTop=$('#appContent').scrollHeight;return}
});
render();
